	.ascii	"boolean-schema-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4692, 22

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4693,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4693,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4693:
	.ascii	"A standalone true or false schema has no class-targeted SHACL shape identity. The definition is omitted rather than inventing a caller vocabulary term."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4693, 151

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4694,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4694,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4694:
	.ascii	"conditional-validation-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4694, 30

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4695,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4695,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4695:
	.ascii	"Schema if/then/else validation chooses constraints from runtime object content. SHACL Core has no equivalent conditional constraint, so independently representable constraints remain and the conditional relationship is omitted."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4695, 227

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4696,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4696,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4696:
	.ascii	"content-validation-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4696, 26

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4697,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4697,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4697:
	.ascii	"String contentEncoding/contentMediaType/contentSchema assertions describe or validate an embedded representation. SHACL Core constrains the RDF literal itself and cannot reproduce that nested content contract."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4697, 209

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4698,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4698,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4698:
	.ascii	"dependency-validation-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4698, 29

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4699,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4699,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4699:
	.ascii	"dependentRequired/dependentSchemas or an equivalent native cross-field dependency has no exact SHACL Core property-shape expression. Individual properties remain while the dependency is omitted."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4699, 194

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4700,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4700,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4700:
	.ascii	"enum-metadata-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4700, 21

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4701,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4701,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4701:
	.ascii	"A schema enum member's generated symbol, title, description, or other parallel metadata is not part of SHACL membership semantics and is omitted while the finite values remain."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4701, 176

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4702,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4702,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4702:
	.ascii	"format-validation-widened"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4702, 25

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4703,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4703,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4703:
	.ascii	"A string format without one exact caller-identifiable RDF datatype is imported as its scalar carrier. PurRDF does not mint or guess a datatype IRI, so format validation is widened and recorded."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4703, 193

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4704,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4704,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4704:
	.ascii	"multiple-of-validation-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4704, 30

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4705,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4705,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4705:
	.ascii	"A numeric multipleOf assertion has no SHACL Core numeric facet. Datatype and range bounds remain while divisibility validation is omitted."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4705, 138

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4706,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4706,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4706:
	.ascii	"non-object-definition-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4706, 29

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4707,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4707,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4707:
	.ascii	"A top-level schema definition describes a scalar, array, finite value set, or alias rather than a class-shaped object. Without a caller-supplied class/property use site it cannot become a top-level SHACL node shape and is omitted."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4707, 230

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4708,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4708,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4708:
	.ascii	"numeric-lexical-form-normalized"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4708, 31

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4709,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4709,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4709:
	.ascii	"A JSON/native numeric value carries numeric value but not the original RDF literal lexical form or derived XSD datatype. The importer uses the canonical configured numeric carrier, so that lexical distinction is normalized."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4709, 223

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4710,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4710,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4710:
	.ascii	"object-key-validation-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4710, 29

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4711,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4711,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4711:
	.ascii	"patternProperties/propertyNames or an equivalent native dynamic-key rule constrains JSON member names. Direct SHACL predicate paths retain named properties, but the dynamic key-space rule is omitted."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4711, 199

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4712,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4712,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4712:
	.ascii	"property-count-validation-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4712, 33

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4713,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4713,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4713:
	.ascii	"minProperties/maxProperties counts JSON object members independently of named predicates. SHACL property shapes retain named requiredness but cannot bound the total predicate count with a Core constraint."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4713, 204

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4714,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4714,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4714:
	.ascii	"schema-applicator-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4714, 25

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4715,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4715,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4715:
	.ascii	"A schema logical applicator cannot be lowered to an equivalent finite SHACL and/or/xone/not shape at its position. Independently representable constraints remain and the applicator is omitted."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4715, 192

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4716,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4716,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4716:
	.ascii	"schema-identity-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4716, 23

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4717,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4717,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4717:
	.ascii	"A schema document identifier, anchor, dialect declaration, generated package identity, or native module identity is not a SHACL vocabulary term. Caller-owned class and property IRIs remain; the carrier identity is omitted."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4717, 222

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4718,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4718,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4718:
	.ascii	"tuple-validation-widened"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4718, 24

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4719,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4719,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4719:
	.ascii	"Position-specific prefixItems/additionalItems or an equivalent tuple type has no direct RDF multi-value ordering contract on one predicate. Common item/cardinality constraints remain and positional validation is widened."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4719, 220

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4720,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4720,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4720:
	.ascii	"unevaluated-validation-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4720, 30

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4721,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4721,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4721:
	.ascii	"unevaluatedProperties/unevaluatedItems depends on schema-applicator evaluation state that SHACL Core does not expose. Local closure, named properties, and item constraints remain while the evaluation-state assertion is omitted."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4721, 227

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4722,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4722,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4722:
	.ascii	"unique-items-validation-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4722, 31

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4723,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4723,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4723:
	.ascii	"uniqueItems constrains duplicate JSON array members. RDF predicate values are a set in the data model, so the serialized-array assertion has no distinct imported SHACL constraint and is omitted."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4723, 194

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4724,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4724,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4724:
	.ascii	"unknown-keyword-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4724, 23

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4725,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4725,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4725:
	.ascii	"A valid extension or assertion outside the fixed importer capability table has no reviewed SHACL interpretation. It is omitted with a located entry rather than silently ignored or guessed."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4725, 188

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4726,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4726,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4726:
	.ascii	"value-term-kind-widened"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4726, 23

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4727,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4727,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4727:
	.ascii	"The schema carrier admits values whose RDF term kind or exact datatype cannot be recovered uniquely. The importer retains the representable scalar/node carrier and records the unresolved term-kind distinction."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4727, 209

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4728,@object
