	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4792,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4792,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4792:
	.ascii	"A named graph the source declares without any row has no spelling in the target syntax, which names a graph only on a row or has no named-graph construct; each such graph is DROPPED and recorded by name at run time."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4792, 215

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4793,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4793,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4793:
	.ascii	"rdfs:range"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4793, 10

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4794,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4794,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4794:
	.ascii	"A predicate's rdfs:range names a value-vocabulary class that conflicts with (or is shadowed by) an explicit sh:class on the same property; the range-derived enum $ref is suppressed in favor of sh:class, and the conflict is recorded rather than silently dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4794, 261

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4795,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4795,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4795:
	.ascii	"sh:SPARQLTarget"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4795, 15

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4796,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4796,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4796:
	.ascii	"A shape targeted only via SHACL-AF sh:target/sh:SPARQLTarget (an arbitrary SPARQL SELECT, not a class extension) has no closed-world JSON Schema equivalent; the shape is excluded from the compiled $defs."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4796, 203

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4797,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4797,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4797:
	.ascii	"sh:disjoint"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4797, 11

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4798,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4798,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4798:
	.ascii	"A SHACL sh:disjoint constraint keeps the values apart from the nodes a property path (an IRI or any other SHACL 1.2 path) reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4798, 287

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4799,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4799,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4799:
	.ascii	"sh:equals"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4799, 9

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4800,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4800,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4800:
	.ascii	"A SHACL sh:equals constraint requires the values to be exactly the nodes a property path (an IRI or any other SHACL 1.2 path) reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4800, 291

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4801,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4801,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4801:
	.ascii	"sh:expression"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4801, 13

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4802,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4802,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4802:
	.ascii	"A SHACL-AF sh:expression node-expression constraint has no JSON Schema equivalent and is dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4802, 97

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4803,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4803,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4803:
	.ascii	"sh:lessThan"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4803, 11

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4804,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4804,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4804:
	.ascii	"A SHACL sh:lessThan constraint orders the values below every node a property path (an IRI or any other SHACL 1.2 path) reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4804, 284

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4805,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4805,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4805:
	.ascii	"sh:lessThanOrEquals"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4805, 19

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4806,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4806,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4806:
	.ascii	"A SHACL sh:lessThanOrEquals constraint orders the values at or below every node a property path (an IRI or any other SHACL 1.2 path) reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4806, 298

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4807,@object
	.section	.rodata.cst16,"aM",@progbits,16
.Lanon.c57b04e44b95a713af94324763ba52bc.4807:
	.ascii	"sh:maxListLength"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4807, 16

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4808,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4808,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4808:
	.ascii	"A SHACL 1.2 sh:maxListLength constraint bounds the member count of a list value node (as maxItems) or focus node (as maxItems of its rdf:rest, less its own member); the instance projection carries a list JSON-LD 1.1 converts (Processing Algorithms and API 8.4.2) as its @list array, which the schema judges exactly; a list it keeps as linked @graph nodes (a cell with another property, referenced twice, or an IRI) is a node reference whose members hang off other @graph nodes, and a JSON Schema keyword judges only the instance location it applies to and those beneath it ($ref resolves schemas, never instance values), so for such a value the constraint is not checked."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4808, 671

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4809,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4809,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4809:
	.ascii	"sh:memberShape"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4809, 14

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4810,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4810,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4810:
	.ascii	"A SHACL 1.2 sh:memberShape constraint judges every member of a list value node or focus node against a shape (as items); the instance projection carries a list JSON-LD 1.1 converts (Processing Algorithms and API 8.4.2) as its @list array, which the schema judges exactly; a list it keeps as linked @graph nodes (a cell with another property, referenced twice, or an IRI) is a node reference whose members hang off other @graph nodes, and a JSON Schema keyword judges only the instance location it applies to and those beneath it ($ref resolves schemas, never instance values), so for such a value the constraint is not checked."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4810, 627

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4811,@object
	.section	.rodata.cst16,"aM",@progbits,16
.Lanon.c57b04e44b95a713af94324763ba52bc.4811:
	.ascii	"sh:minListLength"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4811, 16

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4812,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4812,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4812:
	.ascii	"A SHACL 1.2 sh:minListLength constraint bounds the member count of a list value node (as minItems) or focus node (as minItems of its rdf:rest, less its own member); the instance projection carries a list JSON-LD 1.1 converts (Processing Algorithms and API 8.4.2) as its @list array, which the schema judges exactly; a list it keeps as linked @graph nodes (a cell with another property, referenced twice, or an IRI) is a node reference whose members hang off other @graph nodes, and a JSON Schema keyword judges only the instance location it applies to and those beneath it ($ref resolves schemas, never instance values), so for such a value the constraint is not checked."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4812, 671

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4813,@object
	.section	.rodata.cst8,"aM",@progbits,8
.Lanon.c57b04e44b95a713af94324763ba52bc.4813:
	.ascii	"sh:class"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4813, 8

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4814,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4814,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4814:
	.ascii	"A sh:class constraint on a node shape (one class or a SHACL list of them) judges the focus node's own class membership through the data graph's rdfs:subClassOf* triples, which live on other @graph nodes; a JSON Schema keyword judges only the instance location it applies to and those beneath it, so none reaches them, and the constraint is dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4814, 348

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4815,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4815,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4815:
	.ascii	"sh:closed sh:ByTypes"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4815, 20

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4816,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4816,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4816:
	.ascii	"A SHACL 1.2 sh:closed sh:ByTypes constraint permits the properties each value node's own rdf:type values collect through the shapes graph; an object schema states one fixed key set for every instance, so the object is left open and the constraint is dropped (on a property shape, whose value nodes are node references, likewise)."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4816, 329

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4817,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4817,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4817:
	.ascii	"sh:not"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4817, 6

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4818,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4818,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4818:
	.ascii	"A sh:not negation whose inner shape is not losslessly expressible as a JSON Schema negation (or that appears at property/value position, where negating a base value schema would be vacuous) is dropped rather than emitted unsoundly."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4818, 231

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4819,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4819,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4819:
	.ascii	"sh:nodeByExpression"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4819, 19

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4820,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4820,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4820:
	.ascii	"A SHACL 1.2 sh:nodeByExpression constraint computes its node shape from a node expression evaluated against the data graph; a closed-world JSON Schema has no way to express a shape that is not known until validation time, so the constraint is dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4820, 251

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4821,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4821,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4821:
	.ascii	"sh:rootClass"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4821, 12

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4822,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4822,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4822:
	.ascii	"A SHACL 1.2 sh:rootClass constraint bounds class-valued value nodes (or the focus node) by the data graph's rdfs:subClassOf hierarchy; a closed-world JSON Schema cannot consult that hierarchy, so the constraint is dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4822, 222

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4823,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4823,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4823:
	.ascii	"sh:someValue"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4823, 12

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4824,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4824,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4824:
	.ascii	"A SHACL 1.2 sh:someValue constraint on a property shape requires at least one of the property's values to conform to a shape; the emitted value schema constrains each value alone, so the constraint is dropped (on a node shape it is projected as sh:node is)."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4824, 257

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4825,@object
