	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4876,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4876:
	.ascii	"A property shape whose path is not one predicate (an inverse, sequence, alternative or closure path) constrains no outgoing JSON property of the projected node, so the property shape is dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4876, 194

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4877,@object
