	.ascii	"sh:property"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4877, 11

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4878,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4878,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4878:
	.ascii	"A property shape nested under a property shape or a member shape judges each value node's (or member's) own properties, which live on that node's own @graph node; a JSON Schema keyword judges only the instance location it applies to and those beneath it, so none reaches them, and the nested shape is dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4878, 309

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4879,@object
