	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4880,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4880:
	.ascii	"A SHACL 1.2 sh:reifierShape constraint judges the reifiers of each value's triple, which the projected value does not carry, so the constraint is dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4880, 154

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4881,@object
