	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4881, 22

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4882,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4882,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4882:
	.ascii	"A SHACL 1.2 sh:reificationRequired true constraint requires each value's triple to be reified, which the projected value does not state, so the constraint is dropped."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4882, 166

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4883,@object
