	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4954,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4954,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4954:
	.ascii	"JSON Schema contains/minContains/maxContains constraints have no direct Pydantic v2 field-annotation equivalent; the generated model validates the array container and item type but does not enforce the contains predicate at runtime."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4954, 232

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4955,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4955,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4955:
	.ascii	"JSON Schema if/then/else dependent validation has no direct Pydantic v2 type-annotation equivalent; the conditional is preserved in model_json_schema() but is not enforced by model validation."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4955, 192

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4956,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4956,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4956:
	.ascii	"A JSON Schema string format has no exact dependency-free Pydantic v2 standard-library type; the generated runtime annotation accepts a strict string while model_json_schema() retains the format."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4956, 194

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4957,@object
	.section	.rodata.cst32,"aM",@progbits,32
.Lanon.c57b04e44b95a713af94324763ba52bc.4957:
	.ascii	"inline-object-validation-widened"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4957, 32

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4958,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4958,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4958:
	.ascii	"A Pydantic model or TypedDict with named properties cannot enforce a JSON Schema-valued additionalProperties assertion on every arbitrary extra value; named fields and extra-key policy remain enforced while model_json_schema() retains the complete object schema."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4958, 262

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4959,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4959,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4959:
	.ascii	"intersection-validation-widened"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4959, 31

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4960,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4960,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4960:
	.ascii	"JSON Schema allOf, or anyOf combined conjunctively with structural siblings, has no exact general Pydantic v2 type annotation; runtime validation uses the representable branch information while model_json_schema() retains the complete intersection."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4960, 248

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4961,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4961,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4961:
	.ascii	"A JSON Schema assertion keyword outside the emitter's closed annotation grammar cannot be enforced by the generated Pydantic v2 runtime type; it remains present on model_json_schema() and is recorded at its schema location."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4961, 223

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4962,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4962,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4962:
	.ascii	"negation-validation-dropped"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4962, 27

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4963,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4963,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4963:
	.ascii	"JSON Schema not has no Pydantic v2 type-annotation equivalent, so the generated package evaluates the negated schema over the raw JSON input in a before-validator with a closed keyword table. A negated schema using a keyword outside that table (a regex-selected key, key names, dependencies, evaluation state, a format, content, a non-integer multipleOf, or a pattern outside the common regex grammar) is not evaluated: the positive carrier is validated while model_json_schema() retains the negation."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4963, 501

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4964,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.4964,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.4964:
	.ascii	"one-of-validation-widened"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.4964, 25

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.4965,@object
