	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5014, 37

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5015,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.5015,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.5015:
	.ascii	"Arbitrary JSON Schema patternProperties regular expressions have no equivalent key-space expression in TypeScript. Named and additional-property declarations remain while regex-selected property validation is omitted."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5015, 217

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5016,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.5016,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.5016:
	.ascii	"JSON Schema minProperties/maxProperties count runtime object keys; TypeScript structural declarations express named requiredness but cannot bound the total property count."
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5016, 171

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5017,@object
	.section	.rodata.cst32,"aM",@progbits,32
