	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5976, 104

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5977,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.5977,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.5977:
	.asciz	"\016backreference \300\200\356\000 is not supported -- this is a permanent limitation of this implementation, which translates patterns onto a DFA-based regex engine that cannot backtrack, and no rewriting of the source text can reach a capability the engine does not have"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5977, 258

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5978,@object
	.section	.rodata.str1.1,"aMS",@progbits,1
.Lanon.c57b04e44b95a713af94324763ba52bc.5978:
	.asciz	" unrecognized Unicode block name \300\" in a \\p{...}/\\P{...} block escape"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5978, 70

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5979,@object
.Lanon.c57b04e44b95a713af94324763ba52bc.5979:
	.asciz	"#unrecognized Unicode property name \300\200\024\002 in a \\p{...}/\\P{...} escape: XML Schema Part 2 Appendix G's charProp admits only one of its general-category names (L, Lu, Ll, Lt, Lm, Lo, M, Mn, Mc, Me, N, Nd, Nl, No, P, Pc, Pd, Ps, Pe, Pi, Pf, Po, Z, Zs, Zl, Zp, S, Sm, Sc, Sk, So, C, Cc, Cf, Co, Cn) or an 'Is'-prefixed Unicode block name; Unicode scripts such as \"Greek\", 'key=value'/'key:value' property keys, and regex-crate pseudo-properties are not part of the XSD/XPath dialect -- a script is a different set from a block, so for the Greek block write \\p{IsGreekandCoptic}"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5979, 573

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5980,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.5980,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.5980:
	.ascii	"malformed pattern: pattern ends with a dangling backslash"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5980, 57

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5981,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.5981,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.5981:
	.ascii	"malformed pattern: unterminated character class (missing closing ']')"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5981, 69

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5982,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.5982,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.5982:
	.ascii	"malformed pattern: unescaped '[' inside a character class -- XML Schema Part 2 Appendix G's charGroup defines no nested character class there, so regex-syntax's nested-class union is a different language; a literal '[' must be escaped as '\\['"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5982, 242

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5983,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.5983,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.5983:
	.ascii	"malformed pattern: unescaped ']' outside a character class -- it only ever closes a character class in the XSD/XPath grammar, and a literal one must be escaped as '\\]'"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5983, 167

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5984,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.5984,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.5984:
	.ascii	"malformed pattern: literal ']' at the head of a character class -- XSD's charGroup requires at least one member, and a literal ']' must be escaped as '\\]'"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5984, 154

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5985,@object
	.section	.rodata.str1.1,"aMS",@progbits,1
.Lanon.c57b04e44b95a713af94324763ba52bc.5985:
	.asciz	"\023malformed pattern: \300\2002\001 follows a character-class subtraction operand -- XML Schema Part 2 Appendix G's charGroup ::= (posCharGroup | negCharGroup) ('-' charClassExpr)? makes the subtraction the LAST element of the group, so only the enclosing ']' may follow it; there is at most one subtraction per group and no trailing members"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5985, 331

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5986,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.5986,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.5986:
	.asciz	"\023malformed pattern: \300\200\360\000 is not a construct of the XSD/XPath regular-expression grammar (XML Schema Part 2 Appendix G defines no inline-flag, lookaround, comment, or named-group syntax); the only `(?` group spelling the grammar has is the non-capturing group `(?:`"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5986, 265

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5987,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.5987,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.5987:
	.ascii	"malformed pattern: \\0 is not a construct of the XSD/XPath regular-expression grammar (a back-reference starts at \\1, and \\0 is not a single-character escape)"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5987, 157

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5988,@object
	.section	.rodata..Lanon.c57b04e44b95a713af94324763ba52bc.5988,"a",@progbits
.Lanon.c57b04e44b95a713af94324763ba52bc.5988:
	.asciz	"\024malformed pattern: \\\300\200\313\000 is not a construct of the XSD/XPath regular-expression grammar -- XML Schema Part 2 Appendix G enumerates its single-character escapes exactly (\\n \\r \\t \\\\ \\| \\. \\? \\* \\+ \\( \\) \\{ \\} \\- \\[ \\] \\^), and \\\310\000\000\022 is not among them"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5988, 251

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5989,@object
	.section	.rodata.str1.1,"aMS",@progbits,1
.Lanon.c57b04e44b95a713af94324763ba52bc.5989:
	.asciz	"!malformed pattern: unterminated \\\300%{ block-escape name (no matching '}')"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5989, 74

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5990,@object
.Lanon.c57b04e44b95a713af94324763ba52bc.5990:
	.asciz	"\"malformed pattern: back-reference \300W refers to a capturing group that does not exist, or whose closing ')' comes after it (\300/ capturing group(s) are complete at that point)"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5990, 174

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5991,@object
.Lanon.c57b04e44b95a713af94324763ba52bc.5991:
	.asciz	"\013pattern is \300\032 bytes, which exceeds the \300\013-byte limit"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5991, 54

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5992,@object
.Lanon.c57b04e44b95a713af94324763ba52bc.5992:
	.asciz	"\021pattern contains \300I in-class \\i/\\I/\\c/\\C name escapes under the `i` flag, which exceeds the \300\200\007\001-escape limit -- a standalone name escape is emitted pre-folded and unlimited, but inside a character class it cannot be scoped and the enclosing `i` case-folds its ~917k-codepoint range once per occurrence, so the construct is bounded to keep compile time finite"
	.size	.Lanon.c57b04e44b95a713af94324763ba52bc.5992, 361

	.type	.Lanon.c57b04e44b95a713af94324763ba52bc.5993,@object
